const Context=createContext();const useApp=()=>useContext(Context);const tg=window.Telegram?.WebApp;const isAdmin=location.pathname.startsWith('/admin');
const Logo=Brand;
const Button=VeyraButton;
function IconButton({icon:Icon,label,onClick,className='',disabled=false}){return <button type="button" className={'icon-button '+className} onClick={onClick} aria-label={label} title={label} disabled={disabled}><VeyraIcon icon={Icon} size={23}/></button>}
function countNoun(count,lang,ru,en){return lang==='ru'?ru[{one:0,few:1,many:2}[new Intl.PluralRules('ru').select(count)]??2]:en[count===1?0:1];}
function Empty({icon:Icon=Heart,title,body,children}){const art=Icon===Crown?'premium-crown':Icon===MessageCircle?'chat-bubbles':Icon===Sparkles?'today-coffee':Icon===ShieldCheck?'review-shield':'discover-cards';return <VeyraEmptyState art={art} title={title} body={body}>{children}</VeyraEmptyState>}
function GiftsSoon({onClose}){const{t}=useApp();return <Sheet title={t('Подарки')} onClose={onClose}><div className="gifts-soon"><Artwork name="referral-gift" size={210}/><span className="soon-pill">{t('Скоро')}</span><h2>{t('Красивый способ сказать: ты мне нравишься')}</h2><p>{t('Подарки и коллекции появятся в следующем обновлении.')}</p><Button className="secondary full" onClick={onClose}>{t('Понятно')}</Button></div></Sheet>;}
function GiftCollection(){const{t,setModal}=useApp();return <button type="button" className="gift-collection" onClick={()=>setModal({type:'gifts'})}><Artwork name="referral-gift" size={64}/><span><strong>{t('Коллекция подарков')}</strong><small>{t('Здесь будут полученные подарки')}</small></span><span className="soon-pill">{t('Скоро')}</span></button>;}

function Loading(){const{t}=useApp();return <div className="loading"><LoaderCircle className="spin"/><span>{t('Загрузка…')}</span></div>}
const photoCache=new Map();
function photoSource(id){
 if(!photoCache.has(id)){
  if(photoCache.size>80){const [key,promise]=photoCache.entries().next().value;photoCache.delete(key);promise.then(URL.revokeObjectURL).catch(()=>{});}
  photoCache.set(id,api('/photos/'+id,{raw:true}).then(r=>r.blob()).then(URL.createObjectURL).catch(e=>{photoCache.delete(id);throw e;}));
 }
 return photoCache.get(id);
}
function Photo({id,className='',alt=''}){
 const[url,setUrl]=useState('');const[loaded,setLoaded]=useState(false);
 useEffect(()=>{let alive=true;setUrl('');setLoaded(false);if(id)photoSource(id).then(url=>{if(alive)setUrl(url);}).catch(()=>{});return()=>{alive=false;};},[id]);
 return url?<img src={url} onLoad={()=>setLoaded(true)} className={`${className} photo-image ${loaded?'is-loaded':''}`} alt={alt} draggable={false}/>:<div className={'photo-placeholder '+className} aria-label={alt}><img src="/graphics/placeholders/photo-neutral.svg" width="300" height="300" alt=""/></div>;
}

const sheetScrollLock={count:0,overflow:''};
function Sheet({title,children,onClose,className=''}){
 const[closing,setClosing]=useState(false);const panel=useRef(null);const closeTimer=useRef(null);
 const close=()=>{if(closing)return;setClosing(true);closeTimer.current=setTimeout(onClose,160);};
 useEffect(()=>{const previous=document.activeElement;panel.current?.focus();if(sheetScrollLock.count++===0){sheetScrollLock.overflow=document.body.style.overflow;document.body.style.overflow='hidden';}return()=>{clearTimeout(closeTimer.current);if(--sheetScrollLock.count===0)document.body.style.overflow=sheetScrollLock.overflow;if(previous?.isConnected)previous.focus?.();};},[]);
 return createPortal(<div className={'scrim '+(closing?'closing ':'')+className} onClick={close}><section ref={panel} tabIndex={-1} className="sheet" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()} onKeyDown={e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}if(e.key==='Tab'){e.stopPropagation();const nodes=[...panel.current.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')];const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel.current)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}}><span className="sheet-handle"/><header><h2>{title}</h2><IconButton icon={X} label="Close" onClick={close}/></header>{children}</section></div>,document.body);
}

function App(){
 const[lang,setLang]=useState(tg?.initDataUnsafe?.user?.language_code?.startsWith('ru')?'ru':'en');const[auth,setAuth]=useState('loading');const[authAttempt,setAuthAttempt]=useState(0);const[me,setMe]=useState(null);const[tab,setTab]=useState('feed');const[page,setPage]=useState(null);const[toast,setToast]=useState('');const[modal,setModal]=useState(null);const[busy,setBusy]=useState(false);const[openChatId,setOpenChatId]=useState(null);const[profileView,setProfileView]=useState(null);const[chatOpen,setChatOpen]=useState(false);const[badges,setBadges]=useState({likes:0,chats:0});const[feedFilters,setFeedFilters]=useState(false);
 const t=useCallback(s=>lang==='en'?(en[s]||s):s,[lang]);const refresh=useCallback(async()=>{const m=await api('/me');setMe(m);setLang(m.user.language);return m;},[]);
 const alert=useCallback(s=>setToast(s),[]);useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),4800);return()=>clearTimeout(timer);}},[toast]);
 const run=useCallback(async fn=>{setBusy(true);try{return await fn();}catch(e){alert(lang==='ru'?(errors[e.message]||e.message):(e.message.replaceAll('_',' ').toLowerCase()));}finally{setBusy(false);}},[lang,alert]);
 useEffect(()=>{setAuth('loading');tg?.ready();tg?.expand();tg?.setHeaderColor?.('#09090f');tg?.setBackgroundColor?.('#09090f');if(!tg?.initData){setAuth('outside');return;}post('/auth',{initData:tg.initData,scope:isAdmin?'admin':'user'}).then(async r=>{setSession(r.token);await refresh();setAuth('ok');}).catch(e=>{setAuth('error');alert(errors[e.message]||e.message);});},[authAttempt]);
 useEffect(()=>{if(isAdmin||auth!=='ok'||me?.profile?.moderation!=='approved')return;let alive=true;const poll=()=>{if(document.hidden)return;Promise.all([api('/likes'),api('/matches')]).then(([likes,matches])=>{if(alive)setBadges({likes:likes.count,chats:matches.reduce((sum,m)=>sum+m.unread,0)});}).catch(()=>{});};poll();const timer=setInterval(poll,30000);return()=>{alive=false;clearInterval(timer);};},[auth,me?.profile?.moderation,tab]);
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[page,tab]);
 useEffect(()=>{const viewport=window.visualViewport;const resize=()=>document.documentElement.style.setProperty('--visual-height',`${viewport?.height||window.innerHeight}px`);resize();viewport?.addEventListener('resize',resize);return()=>viewport?.removeEventListener('resize',resize);},[]);
 const switchTab=value=>{setTab(value);setChatOpen(false);setOpenChatId(null);tg?.HapticFeedback?.selectionChanged?.();};
 const openProfile=(profile,options={})=>setProfileView({profile,...options});
 const approved=me?.profile?.moderation==='approved';const ctx={t,lang,setLang,me,refresh,run,busy,alert,tab,setTab:switchTab,page,setPage,modal,setModal,openChatId,setOpenChatId,setChatOpen,setBadges,feedFilters,setFeedFilters,openProfile,closeProfile:()=>setProfileView(null)};
 const shell=isAdmin?'admin-app':chatOpen?'conversation-app':auth==='ok'&&!page&&tab==='feed'&&approved?'feed-app':'member-app';
 return <Context.Provider value={ctx}><div className={'app '+shell}>
 {location.pathname==='/legal'?<Legal/>:auth==='loading'?<div className="boot-screen"><Logo large animated/><Loading/></div>:auth==='error'?<section className="boot-screen"><Logo large/><h1>{t('Нет соединения')}</h1><p className="muted">{t('Проверь интернет и попробуй ещё раз.')}</p><Button className="primary" onClick={()=>setAuthAttempt(n=>n+1)}><RotateCcw size={18}/>{t('Попробовать ещё')}</Button></section>:auth!=='ok'?<Welcome/>:isAdmin?<Admin/>:!me?<Loading/>:<>
 {!chatOpen&&<header className={'topbar '+(approved&&!page&&tab==='feed'?'feed-topbar':'')}>
  {approved&&!page&&tab==='feed'&&<div className="feed-counter" aria-label="Super Likes"><VeyraIcon icon={Star} size={16}/><b>{me.user.superlikes||0}</b><button aria-label="Получить Super Likes" onClick={()=>setPage('premium')}><VeyraIcon icon={Plus} size={16}/></button></div>}
  <Logo/><div className="top-actions">{approved&&<><button className="premium-pill" onClick={()=>setPage('premium')}><VeyraIcon icon={Crown} size={15}/> {new Date(me.user.premium_until)>new Date()?'Premium':'PLUS'}</button><IconButton icon={!page&&tab==='feed'?SlidersHorizontal:SettingsIcon} label={!page&&tab==='feed'?t('Фильтры'):t('Настройки')} onClick={()=>!page&&tab==='feed'?setFeedFilters(true):setPage('settings')}/></>}</div>
 </header>}
 <main className={chatOpen?'conversation-main':''}><div className="view-enter" key={page||tab}>{page?<><button className="back text-button" onClick={()=>setPage(null)}><ChevronLeft size={19}/>{t('Назад')}</button>{page==='edit'?<ProfileForm/>:page==='premium'?<Premium/>:page==='boost'?<BoostPage app={ctx}/>:page==='settings'?<Settings/>:page==='support'?<Support/>:page==='referrals'?<Referrals/>:null}</>:(!me.profile||(me.profile.moderation==='draft'&&me.registration))?<Registration app={ctx} PhotoManager={PhotoManager}/>:!approved?<Onboarding/>:tab==='feed'?<Feed/>:tab==='today'?<Today/>:tab==='likes'?<Likes/>:tab==='chats'?<Chats/>:<Profile/>}</div></main>
 {!page&&approved&&!chatOpen&&<nav className="bottom-nav" aria-label={t('Навигация')}>{[['feed','Лента'],['today','Сегодня'],['likes','Лайки'],['chats','Чаты'],['profile','Профиль']].map(([key,label])=><button key={key} className={tab===key?'selected':''} onClick={()=>switchTab(key)} aria-label={t(label)} aria-current={tab===key?'page':undefined}><span className="nav-icon"><VeyraIcon name={key} size={24}/>{badges[key]>0&&<b className="nav-count">{badges[key]>99?'99+':badges[key]}</b>}</span><span>{t(label)}</span><i/></button>)}</nav>}
 </>}
 {modal?.type==='gifts'&&<GiftsSoon onClose={()=>setModal(null)}/>}
 {modal?.type==='match'&&<MatchCelebration p={modal.profile} onClose={()=>setModal(null)} onProfile={()=>openProfile(modal.profile,{matchId:modal.match_id})} onChat={()=>{setModal(null);setTab('chats');setOpenChatId(modal.match_id||null);}}/>}
 {profileView&&<MemberProfile key={profileView.profile.id} entry={profileView} app={ctx} Photo={Photo} onClose={()=>setProfileView(null)}/>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/><span>{toast}</span><button aria-label="Close" onClick={()=>setToast('')}><X size={17}/></button></div>}
 </div></Context.Provider>;
}
function Welcome(){const{t,lang,setLang}=useApp();const[help,setHelp]=useState(false);return <section className="welcome welcome-photo" style={{'--welcome-image':`url(${welcomeImage})`}}><header><Logo/><button className="language-button" onClick={()=>setLang(lang==='ru'?'en':'ru')}><VeyraIcon icon={Globe} size={15}/>{lang.toUpperCase()}</button></header><div className="welcome-location"><VeyraIcon icon={Globe} size={16}/>{t('Знакомства без границ')}</div><div className="welcome-copy"><span className="eyebrow">A LITTLE CLOSER</span><h1>{t('Твоя следующая')}<em>{t('история любви')}</em><Heart size={30}/></h1><p>{t('Настоящие люди рядом с вами. Новые знакомства, отношения и приятные встречи.')}</p><div className="welcome-promises">{[[UserRound,'Живые знакомства'],[MapPin,'Люди рядом'],[Heart,'Взаимная симпатия']].map(([Icon,label])=><div key={label}><span><Icon size={21}/></span><small>{t(label)}</small></div>)}</div><a className="button primary full" href={'https://t.me/'+(isAdmin?'VeyraAdminBot':'VeyraAppBot')}><Heart size={22} fill="currentColor"/>{t('Открыть в Telegram')}<ArrowRight size={20}/></a><div className="welcome-links"><button className="button secondary" onClick={()=>setHelp(true)}><Play size={16}/>{t('Как это работает')}</button><a className="button secondary" href="/legal"><ShieldCheck size={16}/>{t('Правила')}</a></div><div className="adult-note"><strong>18+</strong><small>{t('Только для совершеннолетних. Уважение, безопасность и взаимное согласие.')}</small></div></div>{help&&<Sheet title={t('Как это работает')} onClose={()=>setHelp(false)}><div className="how-steps">{[['1','Создай анкету','Расскажи о себе и добавь свои фотографии.'],['2','Пройди проверку','Каждая анкета проходит ручную модерацию.'],['3','Найди симпатию','Взаимный лайк открывает ваш личный чат.']].map(([n,title,body])=><div key={n}><b>{n}</b><div><h3>{t(title)}</h3><p>{t(body)}</p></div></div>)}</div></Sheet>}</section>;}
function MatchCelebration({p,onClose,onChat,onProfile}){const{t,me}=useApp();return <Sheet title={t('Взаимная симпатия!')} onClose={onClose} className="match-scene"><div className="match-glow"/><div className="match-sparks" aria-hidden="true">{Array.from({length:9},(_,i)=><Heart key={i} size={10+i%3*6} style={{'--i':i}}/>)}</div><div className="match-title"><Artwork name="match-hearts" size={130}/><h1>{t('У вас')} <em>{t('мэтч!')}</em></h1><p>{t('Вы понравились друг другу')}</p></div><div className="match-people"><div><Photo id={me.photos[0]?.id} alt={me.profile.name}/><h3>{me.profile.name}</h3></div><span className="match-heart"><Heart fill="currentColor"/></span><div><Photo id={p?.photos[0]} alt={p?.name||''}/><h3>{p?.name||'VEYRA'}</h3></div></div><div className="match-note"><Sparkles/><span>{t('Возможно, это начало чего-то особенного')}</span></div><Button className="primary full" onClick={onChat}><MessageCircle fill="currentColor" size={21}/>{t('Перейти в чаты')}<ArrowRight size={19}/></Button><Button className="secondary full" onClick={onProfile}><UserRound size={19}/>{t('Посмотреть профиль')}</Button><Button className="secondary full" onClick={onClose}><Search size={20}/>{t('Продолжить поиск')}</Button></Sheet>;}

function Field({label,children}){return <label className="field"><span>{label}</span>{React.cloneElement(children,{'aria-label':children.props['aria-label']||label})}</label>}
const genders=[['man','Мужчина'],['woman','Женщина']];
function ProfileForm(){const{t,me,refresh,run,busy,setPage,alert}=useApp();const p=me?.profile;const[f,setF]=useState(p?{...p,birth_date:String(p.birth_date).slice(0,10),consent:true}:{name:me?.user.first_name||'',birth_date:'',gender:'man',looking_for:['woman'],bio:'',interests:[],goal:'relationship',city:'',country:'',lat:null,lon:null,min_age:18,max_age:45,radius_km:100,consent:false});const[q,setQ]=useState('');const[places,setPlaces]=useState([]);const upd=(k,v)=>setF(x=>({...x,[k]:v}));
 const locate=()=>{navigator.geolocation?navigator.geolocation.getCurrentPosition(pos=>run(async()=>{const r=await api(`/geo?lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);if(r[0]){setF(x=>({...x,...r[0]}));setPlaces([]);}}),()=>alert(t('Найти город')),{timeout:15000,maximumAge:300000}):alert(t('Найти город'));};
 return <section className="form-page"><span className="eyebrow">YOUR STORY</span><h1>{t(p?'Редактировать':'Сначала — немного о тебе')}</h1><p className="page-subtitle">{t('Расскажи о себе, чтобы мы подобрали интересных людей.')}</p><div className="onboarding-progress"><span className="active"/><i/><span/><i/><span/><small>{t('Анкета → Фото → Проверка')}</small></div><form onSubmit={e=>{e.preventDefault();run(async()=>{await api('/profile',{method:'PUT',body:f});await refresh();setPage(null);});}}>
 <div className="columns"><Field label={t('Имя')}><input value={f.name} maxLength={50} required onChange={e=>upd('name',e.target.value)}/></Field><Field label={t('Дата рождения')}><input type="date" value={f.birth_date} required onChange={e=>upd('birth_date',e.target.value)}/></Field></div>
 <Field label={t('Я')}><select value={f.gender} onChange={e=>{const gender=e.target.value;setF(x=>({...x,gender,...(!p?{looking_for:gender==='man'?['woman']:gender==='woman'?['man']:['man','woman','other']}:{})}));}}>{genders.map(([k,v])=><option key={k} value={k}>{t(v)}</option>)}</select></Field>
 <div className="field"><span>{t('Ищу')}</span><div className="chips">{genders.map(([k,v])=><button type="button" key={k} className={'chip '+(f.looking_for.includes(k)?'active':'')} onClick={()=>upd('looking_for',f.looking_for.includes(k)?f.looking_for.filter(x=>x!==k):[...f.looking_for,k])}>{t(v)}</button>)}</div></div>
 <Field label={t('О себе')}><textarea value={f.bio} maxLength={1000} rows={4} onChange={e=>upd('bio',e.target.value)}/></Field><Field label={t('Интересы через запятую')}><input defaultValue={f.interests.join(', ')} onChange={e=>upd('interests',e.target.value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,7))}/></Field>
 <Field label={t('Цель знакомства')}><select value={f.goal} onChange={e=>upd('goal',e.target.value)}>{[['relationship','Отношения'],['dating','Свидания'],['friends','Дружба'],['unsure','Пока не знаю']].map(([k,v])=><option key={k} value={k}>{t(v)}</option>)}</select></Field>
 <div className="columns">{[['smoking','Курение',[['','Не указано'],['no','Не курю'],['sometimes','Иногда'],['yes','Курю']]],['leisure','Как отдыхаешь?',[['','Не указано'],['active','Активно'],['quiet','Спокойно'],['depends','По настроению']]]].map(([key,label,options])=><Field key={key} label={t(label)}><select value={f[key]||''} onChange={e=>upd(key,e.target.value)}>{options.map(([value,title])=><option key={value} value={value}>{t(title)}</option>)}</select></Field>)}</div><div className="location-box"><span className="muted">{t('Город')}</span>{f.city&&<p><MapPin size={17}/>{f.city}, {f.country}</p>}<div className="inline"><input aria-label={t('Город')} value={q} onChange={e=>setQ(e.target.value)} placeholder={t('Найти город')}/><IconButton icon={Search} label={t('Найти город')} onClick={()=>run(async()=>setPlaces(await api('/geo?q='+encodeURIComponent(q))))}/></div>{places.map((place,i)=><button key={i} type="button" className="place" onClick={()=>{setF(x=>({...x,...place}));setPlaces([]);setQ('');}}>{place.label}</button>)}<button type="button" className="text-button" onClick={locate}><MapPin size={16}/>{t('Определить местоположение')}</button></div>
 <div className="columns"><Field label={t('Возраст от')}><input type="number" min="18" max="110" value={f.min_age} onChange={e=>upd('min_age',+e.target.value)}/></Field><Field label={t('Возраст до')}><input type="number" min={f.min_age} max="110" value={f.max_age} onChange={e=>upd('max_age',+e.target.value)}/></Field></div>
 <Field label={t('Расстояние, км')}><input type="number" min="1" max="20000" value={f.radius_km} onChange={e=>upd('radius_km',+e.target.value)}/></Field>
 {p&&<><h2 className="section-label"><ImageIcon size={20}/>{t('Мои фотографии')}</h2><PhotoManager/></>}<label className="check"><input type="checkbox" checked={f.consent} required onChange={e=>upd('consent',e.target.checked)}/><span>{t('Мне исполнилось 18 лет, я принимаю условия и политику конфиденциальности')} · <a href="/legal" target="_blank" rel="noreferrer">18+</a></span></label>
 <Button type="submit" className="primary full" disabled={busy||!f.city||!f.consent}>{t('Сохранить анкету')}<ChevronRight size={18}/></Button></form></section>;
}
function Onboarding(){const{t,me,setPage,refresh,run,busy}=useApp();const status=me.profile.moderation;const[consent,setConsent]=useState(false);return <section className="moderation-page"><Artwork name="review-shield" size={170}/><h1>{t(status==='pending'?'Анкета на проверке':status==='rejected'?'Нужно поправить анкету':'Добавь свои фотографии')}</h1><p className="muted">{t(status==='pending'?'Проверяем фото и анкету вручную. Сообщим результат в Telegram.':'От 1 до 6 фотографий. Первое фото — главное.')}</p>{me.profile.moderation_reason&&<p className="notice">{me.profile.moderation_reason}</p>}<div className="moderation-preview"><h2>{me.profile.name}</h2><p><MapPin size={14}/>{me.profile.city}</p><p>{me.profile.bio}</p></div><PhotoManager readonly={status==='pending'}/><Button className="secondary full" onClick={()=>setPage('edit')}>{t('Редактировать')}</Button>{status!=='pending'&&<><label className="check"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>{t('Мне исполнилось 18 лет, я принимаю условия и политику конфиденциальности')} · <a href="/legal" target="_blank" rel="noreferrer">{t('Прочитать')}</a></span></label><Button className="primary full" disabled={busy||me.photos.length<1||!consent} onClick={()=>run(async()=>{await post('/profile/submit',{consent:true});await refresh();})}>{t('Отправить анкету на проверку')}<ShieldCheck size={18}/></Button></>}{status==='pending'&&<Button className="primary full" onClick={()=>run(refresh)}>{t('Обновить')}</Button>}<button className="text-button" onClick={()=>setPage('support')}>{t('Поддержка')}</button></section>}
function PhotoManager({readonly=false}){
 const{t,me,run,refresh,busy,alert}=useApp();const[items,setItems]=useState(me.photos);const[dragId,setDragId]=useState(null);const[uploading,setUploading]=useState('');const order=useRef(me.photos);const gesture=useRef(null);const lock=useRef(false);
 useEffect(()=>{if(!gesture.current){setItems(me.photos);order.current=me.photos;}},[me.photos]);
 const reorder=(id,target)=>{const next=[...order.current],from=next.findIndex(p=>p.id===id),to=next.findIndex(p=>p.id===target);if(from<0||to<0||from===to)return;next.splice(to,0,next.splice(from,1)[0]);order.current=next;setItems(next);};
 const save=()=>run(async()=>{try{await api('/photos/order',{method:'PUT',body:{ids:order.current.map(p=>p.id)}});await refresh();}catch(e){order.current=me.photos;setItems(me.photos);throw e;}});
 const files=async(list,replace)=>{if(lock.current)return;lock.current=true;await run(async()=>{try{const all=[...list];if(!replace&&all.length>6-me.photos.length)throw Error(t('Можно добавить не больше шести фото'));for(const [i,file] of all.entries()){if(file.size>5*1024*1024)throw Error(t('Фото должно быть не больше 5 МБ'));setUploading(`${i+1}/${all.length}`);const form=new FormData();form.append('photo',file);await api(replace?'/photos/'+replace:'/photos',{method:replace?'PUT':'POST',body:form});await refresh();}}finally{setUploading('');lock.current=false;}});};
 return <div className="photo-manager"><div className="photo-grid sortable-photos">{items.map((p,i)=><div data-photo-id={p.id} className={'photo-tile '+(p.id===dragId?'photo-dragging':'')} key={p.id}><Photo id={p.id} alt={t('Фото')+' '+(i+1)}/>{i===0&&<span className="photo-main">{t('Главное')}</span>}{!readonly&&<><IconButton icon={X} label={t('Удалить фото')+' '+(i+1)} disabled={busy||!!dragId} onClick={()=>run(async()=>{await api('/photos/'+p.id,{method:'DELETE'});await refresh();})}/><button type="button" className="photo-grip" aria-label={t('Переместить фото')+' '+(i+1)} disabled={busy} onPointerDown={e=>{if(e.button!==0)return;e.preventDefault();gesture.current=order.current.map(p=>p.id).join(',');setDragId(p.id);e.currentTarget.setPointerCapture(e.pointerId);}} onPointerMove={e=>{if(!gesture.current)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-photo-id]')?.dataset.photoId;if(target)reorder(p.id,target);}} onPointerUp={()=>{if(!gesture.current)return;const changed=gesture.current!==order.current.map(p=>p.id).join(',');gesture.current=null;setDragId(null);if(changed)save();}} onPointerCancel={()=>{gesture.current=null;setDragId(null);order.current=me.photos;setItems(me.photos);}} onKeyDown={e=>{if(['ArrowLeft','ArrowUp','ArrowRight','ArrowDown'].includes(e.key)){e.preventDefault();const to=i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1);if(items[to]){reorder(p.id,items[to].id);save();}}}}><MoreHorizontal size={17}/><span>{i+1}</span></button><label className="photo-replace" title={t('Заменить фото')}><ImageIcon size={15}/><input type="file" accept="image/jpeg,image/png,image/webp" aria-label={t('Заменить фото')+' '+(i+1)} disabled={busy} onChange={e=>{if(e.target.files[0])files(e.target.files,p.id);e.target.value='';}}/></label></>}</div>)}{!readonly&&items.length<6&&<label className={'photo-upload '+(busy?'disabled':'')}><Plus/><span>{t('Добавить фото')}</span><small>{items.length+1}/6</small><input type="file" multiple accept="image/jpeg,image/png,image/webp" aria-label={t('Добавить фотографии')} disabled={busy} onChange={e=>{if(e.target.files.length)files(e.target.files);e.target.value='';}}/></label>}{!readonly&&Array.from({length:Math.max(0,5-items.length)},(_,i)=><div className="photo-empty" key={i}><Plus size={18}/><small>{items.length+i+2}</small></div>)}</div>{uploading&&<p className="upload-progress" role="status"><LoaderCircle size={17} className="spin"/>{t('Загрузка фото')} {uploading}</p>}</div>;
}

function Card({p,onReact,onUndo,canUndo}){
 const app=useApp();const{t,run,setModal,busy}=app;const[index,setIndex]=useState(0);const[report,setReport]=useState(false);const[prematch,setPrematch]=useState(false);const[msg,setMsg]=useState('');const[phase,setPhase]=useState('');const gesture=useRef(null);const[drag,setDrag]=useState(0);const suppressClick=useRef(false);const sending=useRef(false);
 useEffect(()=>{setIndex(0);setDrag(0);setPhase('');gesture.current=null;},[p.id]);
 const act=kind=>{if(sending.current)return;sending.current=true;run(async()=>{setPhase('leaving-'+kind);try{const [r]=await Promise.all([post('/reactions',{target:String(p.id),kind,...(msg?{message:msg}:{})}),new Promise(resolve=>setTimeout(resolve,230))]);setPrematch(false);setMsg('');tg?.HapticFeedback?.impactOccurred?.('light');if(r.matched)setModal({type:'match',profile:p,match_id:r.match_id});await onReact();}finally{setPhase('');sending.current=false;}});};
 const viewProfile=()=>app.openProfile(p,{onReact:act,onPrematch:()=>setPrematch(true),onReport:()=>setReport(true),onHandled:onReact});
 const pointerDown=e=>{if(busy||sending.current||e.button!==0||(e.target.closest('button,a,input,textarea')&&!e.target.closest('.photo-controls')))return;suppressClick.current=false;gesture.current={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);};
 const pointerMove=e=>{if(!gesture.current)return;const dx=e.clientX-gesture.current.x,dy=e.clientY-gesture.current.y;setDrag(Math.abs(dx)>Math.abs(dy)*1.2?dx:0);};
 const pointerUp=e=>{if(!gesture.current)return;const dx=e.clientX-gesture.current.x,dy=e.clientY-gesture.current.y;gesture.current=null;setDrag(0);suppressClick.current=Math.abs(dx)>25&&Math.abs(dx)>Math.abs(dy)*1.2;if(dy<-70&&Math.abs(dy)>Math.abs(dx)*1.2&&!busy){suppressClick.current=true;viewProfile();}else if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*1.2&&!busy)act(dx>0?'like':'pass');};
 return <><article key={p.id} className={'dating-card swipe-card '+phase+(drag?' dragging':'')} onClickCapture={e=>{if(suppressClick.current){e.preventDefault();e.stopPropagation();suppressClick.current=false;}}} onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={pointerUp} onPointerCancel={()=>{gesture.current=null;setDrag(0);}} style={drag?{transform:`translateX(${Math.max(-170,Math.min(170,drag))}px) rotate(${drag/30}deg)`}:undefined}>
 <Photo id={p.photos[index]} alt={p.name} className="cover"/>
 {Math.abs(drag)>25&&<span className={'swipe-label '+(drag>0?'yes':'no')}>{t(drag>0?'Нравится':'Пропустить')}</span>}
 <div className="photo-dots">{p.photos.map((x,i)=><button key={x} aria-label={t('Фото')+' '+(i+1)} className={i===index?'on':''} onClick={()=>setIndex(i)}/>)}</div>
 <div className="card-top"><span className="card-status"><BadgeCheck size={14}/>{p.test_profile?'Тестовая анкета':t('Анкета проверена')}</span><div className="inline"><span className="photo-counter">{index+1}/{p.photos.length}</span><IconButton icon={MoreHorizontal} label={t('Пожаловаться')} onClick={()=>setReport(true)}/></div></div>
 {p.photos.length>1&&<div className="photo-controls"><button aria-label={t('Предыдущее фото')} onClick={()=>setIndex((index+p.photos.length-1)%p.photos.length)}/><button aria-label={t('Следующее фото')} onClick={()=>setIndex((index+1)%p.photos.length)}/></div>}
 <div className="card-info">{p.activity&&<span className="today-badge"><span/>{t('Свободен сегодня')}</span>}<h2><button type="button" className="card-name-button" onClick={viewProfile} aria-label={t('Открыть профиль')+' '+p.name}>{p.name}<span>, {p.age}</span><BadgeCheck size={21} className="approved-badge" aria-label={t('Анкета проверена')}/></button></h2><p className="card-location"><MapPin size={15}/>{p.city}{p.distance_km?' · ~'+p.distance_km+' '+t('км'):''}</p><p className="card-online"><i className={p.online?'online':''}/>{p.test_profile?'Тестовая анкета':p.online?t('В сети'):p.last_seen&&Date.now()-new Date(p.last_seen)<86400000?t('Был(а) недавно'):t('Не в сети')}</p><div className="tags goal-tags"><span><Heart size={12}/>{t(({relationship:'Отношения',dating:'Свидания',friends:'Дружба',unsure:'Пока не знаю'})[p.goal]||'Знакомства')}</span></div>{p.interests.length>0&&<div className="tags interest-tags">{p.interests.slice(0,5).map(x=><span key={x}>{x}</span>)}</div>}{p.bio&&<p className="bio">{p.bio}</p>}<button className="card-open-profile" onClick={viewProfile}><UserRound size={14}/>{t('Открыть профиль')}<ChevronRight size={14}/></button><button type="button" className="card-gift-link" onClick={()=>setModal({type:'gifts'})}><Gift size={14}/>{t('Коллекция подарков')}<span>{t('Скоро')}</span></button></div>
 </article><div className="reaction-bar">{onUndo&&<IconButton icon={RotateCcw} className="rewind" label={t('Отменить последнее действие')} onClick={onUndo} disabled={busy||!canUndo}/>}<IconButton icon={X} className="pass" label={t('Пропустить')} onClick={()=>act('pass')} disabled={busy}/><IconButton icon={Heart} className="like" label={t('Нравится')} onClick={()=>act('like')} disabled={busy}/><IconButton icon={Star} className="super" label="Super Like" onClick={()=>act('super')} disabled={busy}/></div>
 {report&&<Report target={p.id} onClose={()=>setReport(false)} onHandled={onReact}/>}{prematch&&<Sheet title={t('Сказать привет')} onClose={()=>setPrematch(false)}><p>{t('Сообщение до мэтча')} · 140</p><textarea aria-label={t('Сообщение до мэтча')} maxLength={140} value={msg} onChange={e=>setMsg(e.target.value)} rows={3}/><Button className="primary full" disabled={!msg.trim()||busy} onClick={()=>act('like')}>{t('Отправить')}<Send size={18}/></Button></Sheet>}</>;
}

function Feed(){
 const{t,run,me,setPage,feedFilters,setFeedFilters,busy}=useApp();const[data,setData]=useState(null);const[last,setLast]=useState(null);const[error,setError]=useState(false);
 const load=useCallback(async()=>{setError(false);try{const [feed,reaction]=await Promise.all([api('/feed'),api('/reactions/last')]);setData(feed);setLast(reaction);}catch(e){setError(true);throw e;}},[]);useEffect(()=>{run(load);},[load]);
 const undo=()=>{if(!last?.premium){setPage('premium');return;}run(async()=>{const result=await post('/reactions/undo',{target:String(last.action.target)});setData(d=>({...d,profiles:[result.profile,...(d?.profiles||[]).filter(p=>p.id!==result.profile.id)]}));setLast(await api('/reactions/last'));});};
 return <section className="feed-surface"><div className="discovery-heading"><div><span className="location-line"><MapPin size={14}/>{me.profile.city}</span></div><span className="feed-allowance">{new Date(me.user.premium_until)>new Date()?'VEYRA PREMIUM':Math.max(0,15-(data?.usage?.likes??me.usage?.likes??0))+' лайков сегодня'}</span></div>{me.user.paused&&<button className="pause-note" onClick={()=>setPage('settings')}><Pause size={14}/>{t('Ваша анкета на паузе')}</button>}
 {data?.profiles.length?<Card p={data.profiles[0]} onReact={load} onUndo={undo} canUndo={last?.can_undo}/>:data?<Empty icon={data.limited?Crown:Heart} title={t(data.limited?'На сегодня всё':'Пока здесь тихо')} body={t(data.limited?'Ты посмотрел 30 анкет. Возвращайся завтра или открой Premium.':'Подходящие анкеты появятся, когда участники рядом пройдут модерацию. Можно расширить радиус в профиле.')}><Button className="secondary" onClick={()=>data.limited?setPage('premium'):run(load)}>{t(data.limited?'Премиум':'Обновить')}</Button>{last?.can_undo&&<Button className="secondary" disabled={busy} onClick={undo}><RotateCcw size={17}/>Вернуть последнюю анкету</Button>}</Empty>:error?<Button onClick={()=>run(load)}>{t('Попробовать ещё')}</Button>:<VeyraSkeleton variant="feed" label={t('Загрузка…')}/>}{feedFilters&&<Filters onClose={()=>setFeedFilters(false)} onSaved={load}/>}</section>;
}

function Filters({onClose,onSaved}){const{t,me,run,refresh,busy}=useApp();const[f,setF]=useState({min_age:me.profile.min_age,max_age:me.profile.max_age,radius_km:me.profile.radius_km,city:me.profile.filter_city||'',looking_for:me.profile.looking_for});return <Sheet title={t('Фильтры')} onClose={onClose}><p>{t('Найди тех, с кем вы на одной волне')}</p><Field label="Город"><input value={f.city} placeholder="Любой город" maxLength={100} onChange={e=>setF({...f,city:e.target.value})}/></Field><div className="segmented-scroll">{[['woman','Женщины'],['man','Мужчины'],['other','Другой пол']].map(([key,label])=><button key={key} className={f.looking_for.includes(key)?'active':''} aria-pressed={f.looking_for.includes(key)} onClick={()=>setF({...f,looking_for:f.looking_for.includes(key)?f.looking_for.filter(x=>x!==key):[...f.looking_for,key]})}>{label}</button>)}</div>{[['min_age','Возраст от'],['max_age','Возраст до'],['radius_km','Расстояние, км']].map(([k,l])=><Field key={k} label={t(l)}><input type="number" min={k==='radius_km'?1:18} max={k==='radius_km'?20000:110} value={f[k]} onChange={e=>setF({...f,[k]:+e.target.value})}/></Field>)}<Button className="primary full" disabled={busy} onClick={()=>run(async()=>{await api('/preferences',{method:'PATCH',body:f});await refresh();onClose();await onSaved?.();})}>{t('Сохранить')}<Check size={18}/></Button></Sheet>;}

const activities=[['coffee','Кофе'],['walk','Прогулка'],['dinner','Ужин'],['cinema','Кино'],['ride','Покататься'],['party','Потусоваться'],['meet','Просто познакомиться']];
function Today(){
 const app=useApp();const{t,lang,me,run,refresh,busy,setModal}=useApp();const[activity,setActivity]=useState(me.today?.activity||'coffee');const[time,setTime]=useState(me.today?.time_slot||'evening');const[data,setData]=useState(null);const[filters,setFilters]=useState(false);const[pendingAvailability,setPendingAvailability]=useState(null);
 const load=useCallback(async()=>setData(await api('/feed?today=true&limit=6')),[]);useEffect(()=>{run(load);},[load]);
 const save=async()=>{const d=new Date();d.setHours(24,0,0,0);await api('/today',{method:'PUT',body:{activity,time_slot:time,expires_at:d.toISOString()}});await refresh();};
 const toggleAvailability=checked=>{setPendingAvailability(checked);run(async()=>{try{if(checked)await save();else{await api('/today',{method:'DELETE'});await refresh();}}finally{setPendingAvailability(null);}});};
 const like=p=>run(async()=>{const r=await post('/reactions',{target:String(p.id),kind:'like'});if(r.matched)setModal({type:'match',profile:p,match_id:r.match_id});await load();});
 return <section className="today-page"><div className="discovery-heading"><div><span className="location-line"><MapPin size={14}/>{me.profile.city}</span><h1>{t('Сегодня')}</h1><p>{t('Люди, которые хотят провести время вместе')}</p></div><IconButton icon={SlidersHorizontal} label={t('Фильтры')} onClick={()=>setFilters(true)}/></div>
 <div className="today-invitation"><div><span className="section-eyebrow">CARPE DIEM</span><h2>{lang==='ru'?'Планы становятся встречами.':'Make a plan. Make a connection.'}</h2><p>{lang==='ru'?'Кофе, прогулка или что-то спонтанное?':'Coffee, a walk, or a little spontaneity?'}</p></div><Artwork name="today-coffee" size={104}/></div><div className="today-plan"><label className="availability-toggle"><span><CalendarDays size={19}/>{t('Я свободен сегодня')}</span><input type="checkbox" role="switch" checked={pendingAvailability??!!me.today} disabled={busy||pendingAvailability!==null} aria-busy={pendingAvailability!==null} onChange={e=>toggleAvailability(e.target.checked)}/></label><div className="segmented time-slots">{[['now',Sun,'Сейчас'],['evening',Sunset,'Вечером'],['after21',Moon,'После 21:00']].map(([key,Icon,label])=><button key={key} className={time===key?'active':''} onClick={()=>setTime(key)}><Icon size={17}/>{t(label)}</button>)}</div><details className="activity-picker"><summary><Coffee size={16}/>{t(activities.find(x=>x[0]===activity)?.[1]||'Кофе')}<span>{t('Выбрать занятие')}</span><ChevronDown size={15}/></summary><div className="chips activity-options">{activities.map(([k,v])=><button key={k} className={'chip '+(activity===k?'active':'')} onClick={e=>{setActivity(k);e.currentTarget.closest('details').open=false;}}>{t(v)}</button>)}</div></details>{me.today&&(activity!==me.today.activity||time!==me.today.time_slot)&&<Button className="primary full" disabled={busy} onClick={()=>run(save)}>{t(me.today?'Сохранить':'Показать мой план')}<ArrowRight size={17}/></Button>}<small className="muted">{t('Статус действует до полуночи по времени устройства.')}</small></div>
 {!data?<VeyraSkeleton variant="today" label={t('Загрузка…')}/>:data.profiles.length?<div className="today-list">{data.profiles.map(p=><article className="today-person" key={p.id}><button className="today-photo" onClick={()=>app.openProfile(p,{onHandled:load})} aria-label={p.name}><Photo id={p.photos[0]} alt={p.name}/><span><ImageIcon size={12}/>{p.photos.length}</span></button><div className="today-person-info"><button className="name-button" onClick={()=>app.openProfile(p,{onHandled:load})}><h3>{p.name}, {p.age}<BadgeCheck size={16}/></h3></button><p className="mini-location"><MapPin size={12}/>{p.city}</p><span className="today-badge"><span/>{t('Свободен сегодня')}</span><small className="time-label">{t(({now:'Сейчас',evening:'Вечером',after21:'После 21:00'})[p.time_slot]||'Сегодня')}</small><p className="today-bio">{p.bio}</p><div className="tags"><span><Coffee size={12}/>{t(activities.find(x=>x[0]===p.activity)?.[1]||'Сегодня')}</span></div></div><div className="today-actions"><IconButton icon={Heart} className="like" label={t('Нравится')+' '+p.name} disabled={busy} onClick={()=>like(p)}/><IconButton icon={MessageCircle} label={t('Открыть анкету')+' '+p.name} onClick={()=>app.openProfile(p,{onHandled:load})}/></div></article>)}</div>:<Empty icon={Sparkles} title={t(data.limited?'На сегодня всё':'Пока здесь тихо')} body={t('Поделись планом — новые знакомства начинаются спонтанно.')}><Button className="secondary" onClick={()=>run(load)}>{t('Обновить')}</Button></Empty>}
 <TodayIdeas app={app} onChoose={a=>{setActivity(a);app.alert('План выбран — включи статус или сохрани изменения выше');document.querySelector('.today-plan')?.scrollIntoView({behavior:'smooth'});}}/>{filters&&<Filters onClose={()=>setFilters(false)} onSaved={load}/>}</section>;
}

function Likes(){
 const app=useApp();const{t,lang,run,setPage,setTab,setBadges}=app;const[data,setData]=useState(null);const load=async()=>{const d=await api('/likes');setData(d);setBadges(x=>({...x,likes:d.count}));};useEffect(()=>{run(load);},[]);
 return <section className="likes-page"><SectionHeading eyebrow={lang==='ru'?'ВЗАИМНОЕ ПРИТЯЖЕНИЕ':'A LITTLE ATTRACTION'} title={t('Лайки')} body={t('Вы кому-то понравились. Ваша история может начаться здесь.')} art="match-hearts"/><LikesHistory app={useApp()} Photo={Photo}/>{!data?<VeyraSkeleton variant="likes" label={t('Загрузка…')}/>:data.count===0?<Empty title={t('Симпатии появятся здесь')} body={t('Заглядывай в ленту и знакомься.')}><Button className="secondary" onClick={()=>setTab('feed')}>{t('Лента')}</Button></Empty>:<><div className="likes-meta"><span><Heart size={17} fill="currentColor"/> {data.count} {countNoun(data.count,lang,['симпатия','симпатии','симпатий'],['like','likes'])}</span><span className="new-likes">{t('Новые лайки')}<i/></span></div>{data.locked?<><div className="likes-paywall"><div className="paywall-copy"><Crown size={28} fill="currentColor"/><h2>{t('Вас лайкнули')}<em>{data.count} {countNoun(data.count,lang,['человек','человека','человек'],['person','people'])}</em></h2><p>{t('Открой Premium, чтобы увидеть, кому ты понравился.')}</p><Button className="primary" onClick={()=>setPage('premium')}><Crown size={17}/>{t('Открыть Premium')}<ChevronRight size={16}/></Button></div><div className="locked-cards" aria-hidden="true"><div><UserRound/></div><div><UserRound/></div><div><Lock/></div></div></div><div className="likes-grid locked-grid">{Array.from({length:Math.min(data.count,6)},(_,i)=><button className="like-tile locked-tile" key={i} onClick={()=>setPage('premium')} aria-label={t('Открыть Premium')}><UserRound className="anonymous-portrait"/><span className="lock-icon"><Lock size={22}/></span><span className="premium-tag"><Crown size={13}/> Premium</span></button>)}</div></>:<div className="likes-grid">{data.profiles.map(p=><button className="like-tile" key={p.id} onClick={()=>app.openProfile(p,{onHandled:load})}><Photo id={p.photos[0]} alt={p.name}/><span className={'tile-heart '+(p.reaction==='super'?'super':'')}><Heart size={18} fill="currentColor"/></span><div><h3>{p.name}, {p.age}<BadgeCheck size={14}/></h3><p><MapPin size={12}/>{p.city}</p>{p.message&&<small><MessageCircle size={12}/>{t('Вам написали')}</small>}</div></button>)}</div>}</>}</section>;
}

function Chats(){
 const{t,lang,run,setTab,openChatId,setOpenChatId,setBadges}=useApp();const[rows,setRows]=useState(null);const[chat,setChat]=useState(null);const[search,setSearch]=useState('');
 const load=useCallback(async()=>{const values=await api('/matches');values.sort((a,b)=>new Date(b.last?.created_at||b.created_at)-new Date(a.last?.created_at||a.created_at));setRows(values);setBadges(x=>({...x,chats:values.reduce((n,m)=>n+m.unread,0)}));},[]);
 useEffect(()=>{run(load);const timer=setInterval(()=>{if(!document.hidden)load().catch(()=>{});},12000);return()=>clearInterval(timer);},[load]);
 useEffect(()=>{if(openChatId&&rows){const next=rows.find(m=>m.id===openChatId);if(next){setChat(next);setOpenChatId(null);}}},[openChatId,rows]);
 if(chat)return <Chat chat={chat} onBack={()=>{setChat(null);run(load);}}/>;
 const visible=rows?.filter(m=>(m.profile.name+' '+(m.last?.body||'')).toLocaleLowerCase().includes(search.toLocaleLowerCase()));
 return <section className="chats-page"><SectionHeading eyebrow={lang==='ru'?'БЛИЖЕ С КАЖДЫМ СЛОВОМ':'CLOSER WITH EVERY WORD'} title={t('Чаты')} body={t('Одно сообщение может изменить всё')} art="chat-bubbles"/><label className="chat-search"><Search size={19}/><input placeholder={t('Поиск по чатам…')} aria-label={t('Поиск по чатам…')} value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch('')} aria-label={t('Очистить поиск')}><X size={16}/></button>}</label>{rows===null?<VeyraSkeleton variant="chats" label={t('Загрузка…')}/>:visible.length?visible.map(m=><button className="chat-row" key={m.id} onClick={()=>setChat(m)}><span className="chat-avatar"><Photo id={m.profile.photos[0]} alt=""/>{m.unread>0&&<i/>}</span><div className="chat-summary"><h3>{m.profile.name}<span>, {m.profile.age}</span></h3><p>{m.blocked_by_me?t('Заблокированные'):m.last?.body||(m.last?.kind==='voice'?(lang==='ru'?'Голосовое сообщение':'Voice message'):m.last?.kind==='image'?(lang==='ru'?'Фотография':'Photo'):m.last?.kind==='sticker'?(lang==='ru'?'Стикер':'Sticker'):t('Сказать привет'))}</p></div><div className="chat-meta"><time>{new Date(m.last?.created_at||m.created_at).toLocaleDateString()===new Date().toLocaleDateString()?new Date(m.last?.created_at||m.created_at).toLocaleTimeString(lang==='ru'?'ru-RU':'en-GB',{hour:'2-digit',minute:'2-digit'}):new Date(m.last?.created_at||m.created_at).toLocaleDateString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short'})}</time>{m.unread>0?<span className="count">{m.unread}</span>:<ChevronRight size={17}/>}</div></button>):<Empty icon={MessageCircle} title={t(search?'Ничего не найдено':'Пока нет переписок')} body={t(search?'Попробуй другое имя или слово из сообщения.':'Взаимный лайк открывает чат.')}>{!search&&<Button className="secondary" onClick={()=>setTab('feed')}>{t('Лента')}</Button>}</Empty>}</section>;
}

function Chat({chat,onBack}){return <MessagesChat key={chat.id} chat={chat} onBack={onBack} app={useApp()} Photo={Photo} Sheet={Sheet}/>;}

function Report({target,onClose,onBlock,onHandled}){
 const{t,lang,run,busy,alert}=useApp();const[reason,setReason]=useState('fake');const[details,setDetails]=useState('');const[confirmBlock,setConfirmBlock]=useState(false);
 return <Sheet title={t(confirmBlock?'Заблокировать':'Пожаловаться')} onClose={onClose}>{confirmBlock?<><div className="confirmation-symbol"><ShieldCheck size={30}/></div><p>{t('Заблокировать пользователя и закрыть чат?')}</p><div className="confirmation-actions"><Button className="secondary full" onClick={()=>setConfirmBlock(false)}>{lang==='ru'?'Назад':'Back'}</Button><Button className="danger full" disabled={busy} onClick={()=>run(async()=>{await post('/blocks',{target:String(target)});onClose();onBlock?.();await onHandled?.();})}>{t('Заблокировать')}</Button></div></>:<><p>{lang==='ru'?'Расскажи, что не так. Команда VEYRA рассмотрит жалобу.':'Tell us what happened. The VEYRA team will review your report.'}</p><div className="report-reasons" role="radiogroup" aria-label={t('Причина жалобы')}>{[['underage','Несовершеннолетний'],['fake','Фейковый профиль'],['harassment','Оскорбления'],['spam','Спам'],['explicit','Откровенный контент'],['other','Другое']].map(([k,v])=><button type="button" role="radio" aria-checked={reason===k} className={reason===k?'selected':''} key={k} onClick={()=>setReason(k)}><span>{t(v)}</span><span className="report-radio">{reason===k&&<Check size={13}/>}</span></button>)}</div><Field label={t('Комментарий')}><textarea value={details} maxLength={2000} rows={3} onChange={e=>setDetails(e.target.value)}/></Field><Button className="primary full" disabled={busy} onClick={()=>run(async()=>{await post('/reports',{target:String(target),reason,details});alert(t('Готово'));onClose();await onHandled?.();})}>{t('Отправить жалобу')}<Flag size={16}/></Button><Button className="danger full" disabled={busy} onClick={()=>setConfirmBlock(true)}><ShieldCheck size={17}/>{t('Заблокировать')}</Button></>}</Sheet>;
}
function PauseToggle(){const{t,me,run,refresh,busy}=useApp();const[pending,setPending]=useState(null);const toggle=paused=>{setPending(paused);run(async()=>{try{await api('/profile/visibility',{method:'PATCH',body:{paused}});await refresh();}finally{setPending(null);}});};return <label className="setting-row pause-setting"><span className="menu-symbol violet"><Pause size={22}/></span><span>{t('Пауза анкеты')}<small>{t('Временно скрыть профиль из поиска')}</small></span><input type="checkbox" role="switch" checked={pending??!!me.user.paused} disabled={busy||pending!==null} aria-busy={pending!==null} onChange={e=>toggle(e.target.checked)}/></label>;}
function Profile(){return <PersonalProfile app={useApp()} Photo={Photo} Sheet={Sheet} Artwork={Artwork} PauseToggle={PauseToggle} GiftCollection={GiftCollection}/>;}

function Premium(){
 const{t,lang,me,run,refresh,alert,busy,setPage}=useApp();const[data,setData]=useState(null);const[category,setCategory]=useState('premium');const[selected,setSelected]=useState(null);useEffect(()=>{run(async()=>setData(await api('/products')));},[]);
 const products=data?.products.filter(p=>p.kind===category)||[];
 useEffect(()=>{const list=data?.products.filter(p=>p.kind===category)||[];setSelected((list.find(p=>p.amount===7)||list[0])?.sku||null);},[data,category]);
 const purchase=()=>run(async()=>{if(!selected)return;const invoice=await post('/payments/invoice',{sku:selected,provider:'stars'});if(tg?.openInvoice)tg.openInvoice(invoice.url,status=>{if(status==='paid')run(refresh);});else window.open(invoice.url,'_blank','noopener');});
 return <section className="premium-page"><div className="premium-hero" style={{'--welcome-image':`url(${welcomeImage})`}}><Artwork name="premium-crown" size={160}/><h1>Premium</h1><p>{t('Больше возможностей')}<br/>{t('для ярких знакомств')}</p></div><div className="perks">{[[Heart,'Кто тебя лайкнул','Узнай, кому ты понравился'],[InfinityIcon,'Безлимитные просмотры и лайки','Знакомься без ограничений'],[Star,'3 Super Likes каждый день','Выделись среди других'],[EyeOff,'Режим инкогнито','Управляй своей видимостью']].map(([Icon,title,body])=><div key={title}><span><Icon size={27}/></span><div><h3>{t(title)}</h3><p>{t(body)}</p></div></div>)}</div>{me.user.premium_until&&new Date(me.user.premium_until)>new Date()&&<p className="notice">{t('Premium активен до')} {new Date(me.user.premium_until).toLocaleString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'long',year:'numeric'})}</p>}<div className="boost-box"><Artwork name="boost-rocket" size={66}/><div><h3>Boost <small>{t('1 Boost в неделю')}</small></h3><p>{t('Поднять анкету на 30 минут')}</p></div><IconButton icon={ChevronRight} label={t('Активировать Boost')} onClick={()=>setPage('boost')}/></div>{new Date(me.user.boost_until)>new Date()&&<p className="notice">{t('Boost активен до')} {new Date(me.user.boost_until).toLocaleTimeString(lang==='ru'?'ru-RU':'en-GB',{hour:'2-digit',minute:'2-digit'})}</p>}<button className="text-button" onClick={()=>run(async()=>{await refresh();alert(t('Сохранено'));})}><VeyraIcon icon={RotateCcw} size={15}/>Обновить статус покупок</button><div className="product-tabs" role="group" aria-label={lang==='en'?'Purchase category':'Категория покупки'}>{[['premium','Premium'],['superlikes','Super Likes'],['boosts','Boost'],['prematches','Pre-match']].map(([key,label])=><button type="button" aria-pressed={category===key} className={category===key?'active':''} key={key} onClick={()=>setCategory(key)}>{label}</button>)}</div>{!data?<Loading/>:<>{!data.enabled&&<p className="notice">{t('Покупки временно выключены')}</p>}<div className="products" role="radiogroup" aria-label={t('Выбери вариант')}>{products.map(p=><button type="button" role="radio" aria-checked={selected===p.sku} className={'product '+(selected===p.sku?'selected ':'')+(p.first_only?'first-offer':'')} key={p.sku} onClick={()=>setSelected(p.sku)}>{p.first_only&&<span className="offer-tag">{t('Первое знакомство')}</span>}<strong>{p.kind==='premium'?(p.amount===1?t('24 часа'):`${p.amount} ${countNoun(p.amount,lang,['день','дня','дней'],['day','days'])}`):p.title}</strong><small>{t(p.kind==='premium'?'Все возможности Premium':'Для новых знакомств')}</small><span className="product-price"><VeyraIcon icon={Star} size={20} fill="currentColor"/>{p.stars}</span>{selected===p.sku&&<VeyraIcon icon={CheckCircle2} size={17} className="plan-check"/>}</button>)}</div><Button className="primary full purchase-button" disabled={busy||!data.enabled||!selected} onClick={purchase}><VeyraIcon icon={Star} fill="currentColor" size={24}/>{t(category==='premium'?'Получить Premium':'Продолжить')}<VeyraIcon icon={ArrowRight} size={22}/></Button></>}<p className="fineprint"><VeyraIcon icon={ShieldCheck} size={16}/>{t('Оплата в Telegram Stars. Без автопродления.')}</p></section>;
}

function Referrals(){return <ReferralsPage app={useApp()}/>;}
function Settings(){return <AccountSettings app={useApp()} Sheet={Sheet} PauseToggle={PauseToggle}/>;}
function Support(){return <SupportPage app={useApp()}/>;}
function Legal(){return <section className="legal"><Logo/><h1>VEYRA · 18+</h1><h2>Условия тестового сервиса</h2><p>Сервис предназначен только для совершеннолетних. Указывайте достоверный возраст, используйте собственные фотографии и уважайте согласие других участников. Запрещены спам, угрозы, домогательства, мошенничество и сексуальный контент. Модератор может отклонять анкеты и блокировать нарушителей. Ручная проверка не является подтверждением личности или гарантией безопасности.</p><h2>Данные и приватность</h2><p>Храним Telegram ID и username, анкету, дату рождения, фотографии, выбранное местоположение, реакции, сообщения и историю покупок. Точные координаты и дата рождения не показываются другим участникам. Собеседники видят возраст и приблизительное расстояние. Telegram username раскрывается только при взаимном согласии. Участники могут сохранять сообщения или делать снимки экрана.</p><p>Данные обрабатываются сервером VEYRA, PostgreSQL и Storage Supabase, Redis Upstash и Telegram. Поиск города использует Geoapify. В настройках доступны экспорт и удаление аккаунта. При удалении фотографии и анкета убираются, чат закрывается, отправленные сообщения удаляются из сервиса. Учёт покупок и записи безопасности могут сохраняться для разбирательств; резервные копии очищаются по графику их хранения.</p><h2>Покупки и помощь</h2><p>Цифровые покупки внутри Telegram оплачиваются Stars. Срок Premium указан до оплаты; автоматического продления нет. Boost увеличивает приоритет в выдаче на 30 минут, но не гарантирует просмотры или знакомства. Для вопросов об оплате и запросов на возврат используйте /paysupport в @VeyraAppBot.</p><p>Тестовый запуск: условия и сведения об операторе должны быть окончательно оформлены перед открытым коммерческим запуском.</p><h2>English</h2><p>Adults 18+ only. Use your own photos and accurate age. Harassment, scams, spam and explicit content are prohibited. Profiles are manually reviewed; this does not verify identity or guarantee safety. Exact coordinates and date of birth are private. Telegram handles are shared only by mutual consent. Export or delete your account in Settings. Purchases use Telegram Stars, have no automatic renewal, and are fulfilled after Telegram confirmation. Boost is a 30-minute ranking priority, with no guaranteed impressions. Contact /paysupport in @VeyraAppBot for payment support and refunds.</p><a className="button secondary" href="/">VEYRA <ChevronRight size={18}/></a></section>}
function meRole(app){return app.me?.user.admin_role||null;}
function Admin(){const app=useApp();const{run,alert,busy}=app;const[detail,setDetail]=useState(null);const[tab,setTab]=useState('dashboard');const[data,setData]=useState(null);const[search,setSearch]=useState('');const[reason,setReason]=useState('');const[confirmAction,setConfirmAction]=useState(null);const[selectedReviews,setSelectedReviews]=useState([]);const[operations,setOperations]=useState(false);const role=meRole(app);const load=useCallback(async()=>{setData(await api('/admin/'+(tab==='users'?'users?q='+encodeURIComponent(search):tab)));},[tab,search]);useEffect(()=>{if(!operations)run(load);},[load,operations]);const act=fn=>run(async()=>{await fn();await load();alert('Готово');});const[promo,setPromo]=useState({code:'',kind:'premium',amount:1,max_uses:10,expires_at:''});if(operations)return <AdminOperations app={app} Sheet={Sheet} onBack={()=>setOperations(false)}/>;return <><header className="topbar"><Logo/><span className="admin-label"><ShieldCheck size={16}/> CONTROL ROOM</span></header><div className="admin-shell"><aside>{[['dashboard','Обзор'],['profiles','Модерация'],['users','Пользователи'],['reports','Жалобы'],['tickets','Поддержка'],['orders','Платежи'],['promos','Промокоды'],['feature_flags','Функции'],['audit_log','Аудит']].filter(([k])=>role==='owner'||k==='dashboard'||(role==='moderator'&&['profiles','reports'].includes(k))||(role==='support'&&k==='tickets')).map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>{setData(null);setTab(k);}}>{v}</button>)}{role==='owner'&&<><button onClick={()=>setOperations(true)}>Управление и аналитика</button><button onClick={()=>run(()=>download('/admin/export.csv','veyra-users.csv'))}><Download size={16}/>Экспорт CSV</button><button disabled={busy} onClick={()=>run(()=>download('/admin/export.zip','veyra-archive.zip'))}><Download size={16}/>Архив с фото и чатами</button></>}</aside><main><div className="section-head"><h1>{({dashboard:'Обзор',profiles:'Очередь модерации',users:'Пользователи',reports:'Жалобы',tickets:'Поддержка',orders:'Платежи',promos:'Промокоды',feature_flags:'Функции',audit_log:'Аудит'})[tab]}</h1><Button className="secondary" onClick={()=>run(load)}>Обновить</Button></div>{tab==='users'&&<input placeholder="ID, username или имя" value={search} onChange={e=>setSearch(e.target.value)}/>} {data===null?<Loading/>:tab==='dashboard'?<div className="dashboard-grid">{Object.entries(data).map(([k,v])=><div className="metric" key={k}><span>{k}</span><strong>{v}</strong></div>)}</div>:tab==='profiles'?data.length?<><div className="account-panel ops-form"><label className="check"><input type="checkbox" checked={selectedReviews.length===data.length} onChange={e=>setSelectedReviews(e.target.checked?data.map(p=>({id:String(p.user_id),revision:p.revision})):[])}/>Выбрать все</label><Button className="secondary" disabled={!selectedReviews.length||busy} onClick={()=>setConfirmAction({text:'Одобрить выбранные анкеты ('+selectedReviews.length+')?',action:async()=>{await post('/admin/profiles/bulk',{profiles:selectedReviews,decision:'approved',reason:'',confirm:true});setSelectedReviews([]);}})}>Одобрить выбранные</Button><input placeholder="Общая причина отклонения" value={reason} onChange={e=>setReason(e.target.value)}/><Button className="danger" disabled={!selectedReviews.length||!reason.trim()||busy} onClick={()=>setConfirmAction({text:'Отклонить выбранные анкеты? Причина: '+reason,action:async()=>{await post('/admin/profiles/bulk',{profiles:selectedReviews,decision:'rejected',reason,confirm:true});setSelectedReviews([]);}})}>Отклонить выбранные</Button></div>{data.map(p=><article className="review-card" key={p.user_id}><label className="check"><input type="checkbox" aria-label={'Выбрать '+p.name} checked={selectedReviews.some(r=>r.id===String(p.user_id))} onChange={e=>setSelectedReviews(e.target.checked?[...selectedReviews,{id:String(p.user_id),revision:p.revision}]:selectedReviews.filter(r=>r.id!==String(p.user_id)))}/>В пакетную проверку</label><div className="review-photos">{p.photos.map(id=><Photo key={id} id={id}/>)}</div><h2>{p.name} · {String(p.birth_date).slice(0,10)}</h2><p>@{p.username||'—'} · ID {p.user_id} · revision {p.revision}</p><p>{p.city}, {p.country} · {p.gender}</p><p>{p.bio}</p><p>{p.interests.join(', ')}</p><input placeholder="Причина отклонения" onChange={e=>setReason(e.target.value)}/><div className="inline"><Button className="primary" onClick={()=>act(()=>post('/admin/profiles/'+p.user_id+'/moderate',{decision:'approved',reason:'',revision:p.revision}))}><CheckCircle2 size={18}/>Одобрить</Button><Button className="danger" onClick={()=>act(()=>post('/admin/profiles/'+p.user_id+'/moderate',{decision:'rejected',reason,revision:p.revision}))}>Отклонить</Button></div></article>)}</>:<Empty icon={ShieldCheck} title="Очередь пуста" body="Новые анкеты появятся после отправки на проверку."/>:tab==='feature_flags'?data.map(f=><label className="setting-row" key={f.key}><span>{f.key}<small>{JSON.stringify(f.config)}</small></span><input type="checkbox" checked={f.enabled} onChange={e=>act(()=>api('/admin/feature_flags/'+f.key,{method:'PATCH',body:{enabled:e.target.checked}}))}/></label>):tab==='tickets'?data.map(t=><article className="ticket" key={t.id}><small>{t.user_id} · {t.status}</small><p>{t.body}</p>{t.reply&&!t.messages?.length&&<blockquote>{t.reply}</blockquote>}{t.messages?.map((m,i)=><blockquote key={i}><small>{m.is_staff?'VEYRA':'Пользователь'}</small><p>{m.body}</p></blockquote>)}{t.status==='open'&&<form onSubmit={e=>{e.preventDefault();const reply=new FormData(e.currentTarget).get('reply');act(()=>post('/admin/tickets/'+t.id+'/reply',{reply}));}}><textarea name="reply" placeholder="Ответ" required maxLength={3000}/><Button className="primary" type="submit">Ответить</Button></form>}</article>):<>{tab==='promos'&&<form className="promo-form" onSubmit={e=>{e.preventDefault();act(()=>post('/admin/promos',{...promo,expires_at:new Date(promo.expires_at).toISOString()}));}}><input placeholder="CODE" value={promo.code} onChange={e=>setPromo({...promo,code:e.target.value.toUpperCase()})} required/><select value={promo.kind} onChange={e=>setPromo({...promo,kind:e.target.value})}>{['premium','superlikes','boosts','prematches'].map(x=><option key={x}>{x}</option>)}</select><Field label="Дни / количество"><input type="number" min="1" value={promo.amount} onChange={e=>setPromo({...promo,amount:+e.target.value})}/></Field><Field label="Лимит использований"><input type="number" min="1" value={promo.max_uses} onChange={e=>setPromo({...promo,max_uses:+e.target.value})}/></Field><input type="datetime-local" required value={promo.expires_at} onChange={e=>setPromo({...promo,expires_at:e.target.value})}/><Button type="submit" className="primary">Создать</Button></form>}<div className="table-wrap"><table><thead><tr>{(data[0]?Object.keys(data[0]):[]).map(k=><th key={k}>{k}</th>)}{['users','reports','orders'].includes(tab)&&<th>Действия</th>}</tr></thead><tbody>{data.map((r,i)=><tr key={r.id||r.code||i}>{Object.entries(r).map(([k,v])=><td key={k}>{typeof v==='object'?JSON.stringify(v):String(v??'—')}</td>)}{tab==='users'&&<td><Button className="secondary" onClick={()=>run(async()=>setDetail(await api('/admin/users/'+r.id)))}>Открыть</Button><Button className="secondary" onClick={()=>setConfirmAction({text:r.status==='banned'?'Разблокировать пользователя?':'Заблокировать пользователя?',action:()=>post('/admin/users/'+r.id+'/status',{status:r.status==='banned'?'active':'banned'})})}>{r.status==='banned'?'Разблокировать':'Заблокировать'}</Button></td>}{tab==='orders'&&<td>{r.status==='paid'&&<Button className="danger" onClick={()=>{setConfirmAction({text:'Вернуть Stars по этому платежу?',action:()=>post('/admin/orders/'+r.id+'/refund')});}}>Вернуть Stars</Button>}</td>}{tab==='reports'&&<td><Button onClick={()=>act(()=>post('/admin/reports/'+r.id+'/resolve'))}>Закрыть</Button>{role==='owner'&&<Button className="danger" onClick={()=>setConfirmAction({text:'Заблокировать пользователя?',action:()=>post('/admin/users/'+r.target+'/status',{status:'banned'})})}>Блокировать</Button>}</td>}</tr>)}</tbody></table>{!data.length&&<p className="muted">Нет данных</p>}</div></>}</main></div>{confirmAction&&<Sheet title="Подтверждение" onClose={()=>setConfirmAction(null)}><p>{confirmAction.text}</p><Button className="danger full" disabled={busy} onClick={()=>act(async()=>{await confirmAction.action();setConfirmAction(null);})}>Подтвердить</Button></Sheet>}{detail&&<AdminUserDetail detail={detail} onClose={()=>setDetail(null)}/>}</>}
function AdminUserDetail({detail,onClose}){
 const{run,busy}=useApp();const{user,profile,photos,chats}=detail;
 return <Sheet title={profile?.name||user.first_name||String(user.id)} onClose={onClose}>
  <p>ID {user.id} · @{user.username||'—'} · {user.status}</p>
  <div className="review-photos">{photos.map(photo=><Photo key={photo.id} id={photo.id} alt={profile?.name||''}/>)}</div>
  {profile&&<><p>{profile.city}, {profile.country} · {String(profile.birth_date).slice(0,10)}</p><p>{profile.bio}</p><p>Модерация: {profile.moderation}</p></>}
  <p>Регистрация: {new Date(user.created_at).toLocaleString('ru-RU')}</p>
  <p>Пригласил: {user.referrer_id||'—'} · Premium: {user.premium_until?new Date(user.premium_until).toLocaleString('ru-RU'):'—'}</p>
  <Button className="primary full" disabled={busy} onClick={()=>run(()=>download('/admin/users/'+user.id+'/export.zip','veyra-user-'+user.id+'.zip'))}><Download size={18}/>Скачать анкету, фото и чаты</Button>
  <h3>Переписки ({chats.length})</h3>
  {chats.map(chat=><article className="ticket" key={chat.id}><strong>{chat.other_name||chat.other_id}</strong><p>ID {chat.other_id} · {chat.message_count} сообщений · {chat.active?'Активен':'Завершён'}</p><small>{chat.id}.jsonl</small></article>)}
  {!chats.length&&<p className="muted">Переписок пока нет.</p>}
 </Sheet>;
}
